/**
 * FastArt Media Container Duration Patcher
 * 
 * Accurately patches movie header durations in MP4 (ISO/IEC 14496-12) and WebM (EBML)
 * containers generated by browser/WebView MediaRecorder or streaming encoders.
 *
 * MediaRecorder streams chunks live with unfinalized headers (mvhd/tkhd duration = 0 or
 * fragment default ~4s, or WebM Segment Info without a Duration element).
 * This utility inspects the container header and injects or rewrites the exact duration
 * into:
 *   - MP4: mvhd (Movie Header), tkhd (Track Header), mdhd (Media Header), and mehd (Movie Extends Header)
 *   - WebM: Segment Info -> Duration (0x4489) scaled according to TimecodeScale (0x2AD7B1),
 *           updating Info VINT length, SeekHead SeekPosition offsets, and Segment size.
 */

export function patchMediaContainerDuration(
  bytes: Uint8Array,
  durationSec: number
): Uint8Array {
  if (!bytes || bytes.length < 16 || !durationSec || durationSec <= 0) {
    return bytes;
  }

  // ---------------------------------------------------------------------------
  // 1. Detect MP4 Container: Check for 'ftyp' in first 64 bytes or 'moov'
  // ---------------------------------------------------------------------------
  let isMp4 = false;
  for (let i = 4; i <= Math.min(bytes.length - 4, 64); i++) {
    if (
      bytes[i] === 0x66 && // 'f'
      bytes[i + 1] === 0x74 && // 't'
      bytes[i + 2] === 0x79 && // 'y'
      bytes[i + 3] === 0x70 // 'p'
    ) {
      isMp4 = true;
      break;
    }
  }

  if (isMp4) {
    try {
      const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
      let offset = 0;
      const fileLen = bytes.length;

      let moovOffset = -1;
      let moovSize = 0;

      while (offset + 8 <= fileLen) {
        let boxSize = dv.getUint32(offset);
        const boxType = String.fromCharCode(
          bytes[offset + 4],
          bytes[offset + 5],
          bytes[offset + 6],
          bytes[offset + 7]
        );

        if (boxSize === 1 && offset + 16 <= fileLen) {
          // 64-bit size (large box)
          const high = dv.getUint32(offset + 8);
          const low = dv.getUint32(offset + 12);
          boxSize = high * 4294967296 + low;
          if (boxType === "moov") {
            moovOffset = offset + 16;
            moovSize = boxSize - 16;
            break;
          }
          offset += boxSize;
        } else if (boxSize >= 8) {
          if (boxType === "moov") {
            moovOffset = offset + 8;
            moovSize = boxSize - 8;
            break;
          }
          offset += boxSize;
        } else {
          break;
        }
      }

      if (moovOffset >= 0) {
        const moovEnd = Math.min(fileLen, moovOffset + moovSize);

        // PASS 1: Find mvhd first to guarantee movieTimescale is known before patching tracks
        let movieTimescale = 1000;
        let foundMovieTimescale = false;

        const findMvhd = (start: number, end: number) => {
          let cur = start;
          while (cur + 8 <= end) {
            let bSize = dv.getUint32(cur);
            const bType = String.fromCharCode(
              bytes[cur + 4],
              bytes[cur + 5],
              bytes[cur + 6],
              bytes[cur + 7]
            );
            let headerLen = 8;
            if (bSize === 1 && cur + 16 <= end) {
              const h = dv.getUint32(cur + 8);
              const l = dv.getUint32(cur + 12);
              bSize = h * 4294967296 + l;
              headerLen = 16;
            } else if (bSize < 8) {
              break;
            }
            const bEnd = Math.min(end, cur + bSize);

            if (bType === "mvhd") {
              const v = bytes[cur + headerLen];
              if (v === 0 && cur + headerLen + 16 <= bEnd) {
                const ts = dv.getUint32(cur + headerLen + 12);
                if (ts > 0) {
                  movieTimescale = ts;
                  foundMovieTimescale = true;
                }
              } else if (v === 1 && cur + headerLen + 24 <= bEnd) {
                const ts = dv.getUint32(cur + headerLen + 20);
                if (ts > 0) {
                  movieTimescale = ts;
                  foundMovieTimescale = true;
                }
              }
              return;
            } else if (
              bType === "trak" ||
              bType === "mdia" ||
              bType === "minf" ||
              bType === "mvex"
            ) {
              findMvhd(cur + headerLen, bEnd);
              if (foundMovieTimescale) return;
            }
            cur += bSize;
          }
        };

        findMvhd(moovOffset, moovEnd);

        // PASS 2: Patch mvhd, tkhd, mdhd, and mehd with correct timescales & 64-bit offsets
        const scanBoxes = (start: number, end: number) => {
          let cur = start;
          while (cur + 8 <= end) {
            let bSize = dv.getUint32(cur);
            const bType = String.fromCharCode(
              bytes[cur + 4],
              bytes[cur + 5],
              bytes[cur + 6],
              bytes[cur + 7]
            );
            let headerLen = 8;
            if (bSize === 1 && cur + 16 <= end) {
              const h = dv.getUint32(cur + 8);
              const l = dv.getUint32(cur + 12);
              bSize = h * 4294967296 + l;
              headerLen = 16;
            } else if (bSize < 8) {
              break;
            }
            const bEnd = Math.min(end, cur + bSize);

            if (bType === "mvhd") {
              const v = bytes[cur + headerLen];
              const dur = Math.round(durationSec * movieTimescale);
              if (v === 0 && cur + headerLen + 20 <= bEnd) {
                dv.setUint32(cur + headerLen + 16, dur);
              } else if (v === 1 && cur + headerLen + 32 <= bEnd) {
                dv.setUint32(cur + headerLen + 24, Math.floor(dur / 4294967296));
                dv.setUint32(cur + headerLen + 28, dur >>> 0);
              }
            } else if (bType === "tkhd") {
              const v = bytes[cur + headerLen];
              const dur = Math.round(durationSec * movieTimescale);
              if (v === 0 && cur + headerLen + 24 <= bEnd) {
                dv.setUint32(cur + headerLen + 20, dur);
              } else if (v === 1 && cur + headerLen + 36 <= bEnd) {
                dv.setUint32(cur + headerLen + 28, Math.floor(dur / 4294967296));
                dv.setUint32(cur + headerLen + 32, dur >>> 0);
              }
            } else if (bType === "mdhd") {
              const v = bytes[cur + headerLen];
              if (v === 0 && cur + headerLen + 20 <= bEnd) {
                const mdTimescale = dv.getUint32(cur + headerLen + 12);
                if (mdTimescale > 0) {
                  const mdDur = Math.round(durationSec * mdTimescale);
                  dv.setUint32(cur + headerLen + 16, mdDur);
                }
              } else if (v === 1 && cur + headerLen + 32 <= bEnd) {
                const mdTimescale = dv.getUint32(cur + headerLen + 20);
                if (mdTimescale > 0) {
                  const mdDur = Math.round(durationSec * mdTimescale);
                  dv.setUint32(cur + headerLen + 24, Math.floor(mdDur / 4294967296));
                  dv.setUint32(cur + headerLen + 28, mdDur >>> 0);
                }
              }
            } else if (bType === "mehd") {
              const v = bytes[cur + headerLen];
              const dur = Math.round(durationSec * movieTimescale);
              if (v === 0 && cur + headerLen + 8 <= bEnd) {
                dv.setUint32(cur + headerLen + 4, dur);
              } else if (v === 1 && cur + headerLen + 12 <= bEnd) {
                dv.setUint32(cur + headerLen + 4, Math.floor(dur / 4294967296));
                dv.setUint32(cur + headerLen + 8, dur >>> 0);
              }
            } else if (
              bType === "trak" ||
              bType === "mdia" ||
              bType === "minf" ||
              bType === "mvex"
            ) {
              scanBoxes(cur + headerLen, bEnd);
            }
            cur += bSize;
          }
        };

        scanBoxes(moovOffset, moovEnd);
      }
      return bytes;
    } catch (e) {
      console.warn("[mediaDurationPatcher] MP4 duration patch error:", e);
      return bytes;
    }
  }

  // ---------------------------------------------------------------------------
  // 2. Detect WebM Container: EBML ID [0x1A, 0x45, 0xDF, 0xA3]
  // ---------------------------------------------------------------------------
  const isWebM =
    bytes[0] === 0x1a &&
    bytes[1] === 0x45 &&
    bytes[2] === 0xdf &&
    bytes[3] === 0xa3;

  if (isWebM) {
    try {
      const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
      let pos = 0;
      const fileLen = bytes.length;

      const readEbmlId = (p: number): { id: number; length: number } | null => {
        if (p >= fileLen) return null;
        const b0 = bytes[p];
        if (b0 & 0x80) return { id: b0, length: 1 };
        if (b0 & 0x40 && p + 1 < fileLen) return { id: (b0 << 8) | bytes[p + 1], length: 2 };
        if (b0 & 0x20 && p + 2 < fileLen)
          return { id: (b0 << 16) | (bytes[p + 1] << 8) | bytes[p + 2], length: 3 };
        if (b0 & 0x10 && p + 3 < fileLen)
          return {
            id: ((b0 << 24) >>> 0) | (bytes[p + 1] << 16) | (bytes[p + 2] << 8) | bytes[p + 3],
            length: 4,
          };
        return null;
      };

      const readVint = (p: number): { value: number; length: number } | null => {
        if (p >= fileLen) return null;
        const b0 = bytes[p];
        let mask = 0x80;
        let len = 1;
        while (len <= 8 && !(b0 & mask)) {
          mask >>= 1;
          len++;
        }
        if (len > 8 || p + len > fileLen) return null;
        let val = b0 & (mask - 1);
        for (let i = 1; i < len; i++) {
          val = val * 256 + bytes[p + i];
        }
        return { value: val, length: len };
      };

      // Skip EBML Header
      const ebmlId = readEbmlId(pos);
      if (!ebmlId || ebmlId.id !== 0x1a45dfa3) return bytes;
      pos += ebmlId.length;
      const ebmlSize = readVint(pos);
      if (!ebmlSize) return bytes;
      pos += ebmlSize.length + ebmlSize.value;

      // Find Segment [0x18, 0x53, 0x80, 0x67]
      const segId = readEbmlId(pos);
      if (!segId || segId.id !== 0x18538067) return bytes;
      pos += segId.length;
      const segSizePos = pos;
      const segSize = readVint(pos);
      if (!segSize) return bytes;
      pos += segSize.length;
      const segDataStart = pos;

      // Search inside Segment for SeekHead and Info elements
      let infoPos = -1;
      let infoDataPos = -1;
      let infoDataSize = -1;
      let infoVintPos = -1;
      let infoVintLen = -1;
      let seekHeadPos = -1;
      let seekHeadEnd = -1;

      while (pos + 4 < fileLen) {
        const elId = readEbmlId(pos);
        if (!elId) break;
        if (elId.id === 0x114d9b74) {
          // SeekHead element
          seekHeadPos = pos;
          const v = readVint(pos + elId.length);
          if (v) seekHeadEnd = pos + elId.length + v.length + v.value;
          pos += elId.length + (v ? v.length + v.value : 0);
        } else if (elId.id === 0x1549a966) {
          // Segment Info element
          infoPos = pos;
          infoVintPos = pos + elId.length;
          const v = readVint(infoVintPos);
          if (v) {
            infoVintLen = v.length;
            infoDataPos = infoVintPos + v.length;
            infoDataSize = v.value;
          }
          break;
        } else if (elId.id === 0x1f43b675 || elId.id === 0x1654ae6b) {
          // Reached Cluster or Tracks without finding Info
          break;
        } else {
          const v = readVint(pos + elId.length);
          if (!v) break;
          pos += elId.length + v.length + v.value;
        }
      }

      if (infoDataPos >= 0) {
        const infoEnd = Math.min(fileLen, infoDataPos + infoDataSize);
        let timecodeScale = 1000000; // default 1ms (1,000,000 ns)
        let durOffset = -1;
        let durSize = 0;
        let voidOffset = -1;
        let voidSize = 0;

        let ip = infoDataPos;
        while (ip < infoEnd) {
          const subId = readEbmlId(ip);
          if (!subId) break;
          const sv = readVint(ip + subId.length);
          if (!sv) break;
          const valPos = ip + subId.length + sv.length;

          if (subId.id === 0x2ad7b1) {
            // TimecodeScale
            let tc = 0;
            for (let k = 0; k < sv.value; k++) tc = tc * 256 + bytes[valPos + k];
            if (tc > 0) timecodeScale = tc;
          } else if (subId.id === 0x4489) {
            // Duration
            durOffset = valPos;
            durSize = sv.value;
          } else if (subId.id === 0xec) {
            // Void element
            voidOffset = ip;
            voidSize = subId.length + sv.length + sv.value;
          }
          ip = valPos + sv.value;
        }

        const durationInScale = (durationSec * 1000000000) / timecodeScale;

        // Path 1: Duration element is already present in Info
        if (durOffset >= 0) {
          if (durSize === 4) {
            dv.setFloat32(durOffset, durationInScale);
            return bytes;
          } else if (durSize === 8) {
            dv.setFloat64(durOffset, durationInScale);
            return bytes;
          }
        }

        // Path 2: Check if Void element in Info is available to overwrite in-place
        if (voidOffset >= 0 && voidSize >= 7) {
          if (voidSize >= 11) {
            // Overwrite with 8-byte Float64
            bytes[voidOffset] = 0x44;
            bytes[voidOffset + 1] = 0x89;
            bytes[voidOffset + 2] = 0x88;
            dv.setFloat64(voidOffset + 3, durationInScale);
            const rem = voidSize - 11;
            if (rem >= 2) {
              bytes[voidOffset + 11] = 0xec;
              bytes[voidOffset + 12] = 0x80 | (rem - 2);
            }
            return bytes;
          } else {
            // Overwrite with 4-byte Float32
            bytes[voidOffset] = 0x44;
            bytes[voidOffset + 1] = 0x89;
            bytes[voidOffset + 2] = 0x84;
            dv.setFloat32(voidOffset + 3, durationInScale);
            const rem = voidSize - 7;
            if (rem >= 2) {
              bytes[voidOffset + 7] = 0xec;
              bytes[voidOffset + 8] = 0x80 | (rem - 2);
            }
            return bytes;
          }
        }

        // Path 3: Duration is absent (standard Chromium MediaRecorder output with timeslice).
        // Inject Duration element [0x44, 0x89, 0x88, 8-byte Float64] into Info, update Info VINT,
        // and adjust SeekHead SeekPositions for subsequent elements (Tracks, Clusters).
        const durBytes = new Uint8Array(11);
        durBytes[0] = 0x44;
        durBytes[1] = 0x89;
        durBytes[2] = 0x88; // 1-byte VINT indicating 8 bytes payload
        new DataView(durBytes.buffer).setFloat64(3, durationInScale);
        const injectLen = durBytes.length; // 11 bytes

        const newInfoDataSize = infoDataSize + injectLen;
        let newBytes: Uint8Array;

        if (infoVintLen === 1 && newInfoDataSize <= 127) {
          newBytes = new Uint8Array(bytes.length + injectLen);
          newBytes.set(bytes.subarray(0, infoEnd), 0);
          newBytes.set(durBytes, infoEnd);
          newBytes.set(bytes.subarray(infoEnd), infoEnd + injectLen);
          newBytes[infoVintPos] = 0x80 | newInfoDataSize;
        } else {
          let bCount = 1;
          let limit = 127;
          while (bCount <= 8 && newInfoDataSize > limit) {
            bCount++;
            limit = (limit << 7) | 0x7f;
          }
          const vBuf = new Uint8Array(bCount);
          let rem = newInfoDataSize;
          const flag = 1 << (7 - (bCount - 1));
          vBuf[0] = flag | Math.floor(rem / Math.pow(256, bCount - 1));
          for (let i = 1; i < bCount; i++) {
            vBuf[i] = Math.floor(rem / Math.pow(256, bCount - 1 - i)) % 256;
          }
          const deltaVint = bCount - infoVintLen;
          newBytes = new Uint8Array(bytes.length + injectLen + deltaVint);
          newBytes.set(bytes.subarray(0, infoVintPos), 0);
          newBytes.set(vBuf, infoVintPos);
          newBytes.set(bytes.subarray(infoDataPos, infoEnd), infoVintPos + bCount);
          newBytes.set(durBytes, infoVintPos + bCount + infoDataSize);
          newBytes.set(bytes.subarray(infoEnd), infoVintPos + bCount + newInfoDataSize);
        }

        const totalShift = newBytes.length - bytes.length;

        // If SeekHead exists before Info, update SeekPosition for elements that come after Info
        if (seekHeadPos >= 0 && seekHeadEnd > seekHeadPos) {
          let sp = seekHeadPos;
          const shId = readEbmlId(sp);
          if (shId) {
            sp += shId.length;
            const shv = readVint(sp);
            if (shv) {
              sp += shv.length;
              const shLimit = sp + shv.value;
              while (sp + 4 < shLimit) {
                const sid = readEbmlId(sp);
                if (!sid) break;
                const sv = readVint(sp + sid.length);
                if (!sv) break;
                const seekContentStart = sp + sid.length + sv.length;
                const nextSeek = seekContentStart + sv.value;

                if (sid.id === 0x4dbb) {
                  // Seek element: contains SeekID (0x53AB) and SeekPosition (0x53AC)
                  let kp = seekContentStart;
                  let sPosOffset = -1;
                  let sPosLen = 0;
                  while (kp < nextSeek) {
                    const kid = readEbmlId(kp);
                    if (!kid) break;
                    const kv = readVint(kp + kid.length);
                    if (!kv) break;
                    const kvalPos = kp + kid.length + kv.length;
                    if (kid.id === 0x53ac) {
                      sPosOffset = kvalPos;
                      sPosLen = kv.value;
                    }
                    kp = kvalPos + kv.value;
                  }
                  if (sPosOffset >= 0 && sPosLen > 0 && sPosLen <= 8) {
                    let curPos = 0;
                    for (let b = 0; b < sPosLen; b++) curPos = curPos * 256 + newBytes[sPosOffset + b];
                    // If this element was located at or after Info, shift its SeekPosition
                    if (curPos >= (infoPos - segDataStart)) {
                      curPos += totalShift;
                      for (let b = sPosLen - 1; b >= 0; b--) {
                        newBytes[sPosOffset + b] = curPos % 256;
                        curPos = Math.floor(curPos / 256);
                      }
                    }
                  }
                }
                sp = nextSeek;
              }
            }
          }
        }

        // If Segment size is definite (not unknown 0x01FFFFFFFFFFFFFF), increment it
        if (segSize && segSize.length <= 8) {
          const isUnknown = segSize.length === 8 &&
            bytes[segSizePos] === 0x01 &&
            bytes[segSizePos + 1] === 0xff &&
            bytes[segSizePos + 2] === 0xff &&
            bytes[segSizePos + 3] === 0xff &&
            bytes[segSizePos + 4] === 0xff &&
            bytes[segSizePos + 5] === 0xff &&
            bytes[segSizePos + 6] === 0xff &&
            bytes[segSizePos + 7] === 0xff;
          if (!isUnknown && segSize.value > 0) {
            let curSegVal = segSize.value + totalShift;
            const mask = 1 << (7 - (segSize.length - 1));
            for (let b = segSize.length - 1; b >= 0; b--) {
              if (b === 0) {
                newBytes[segSizePos + b] = mask | (curSegVal % mask);
              } else {
                newBytes[segSizePos + b] = curSegVal % 256;
                curSegVal = Math.floor(curSegVal / 256);
              }
            }
          }
        }

        return newBytes;
      }
      return bytes;
    } catch (e) {
      console.warn("[mediaDurationPatcher] WebM duration patch error:", e);
      return bytes;
    }
  }

  return bytes;
}
